('apple-20w-usbc-power-adapter-gen2', 'Apple 20W USB-C Power Adapter Gen 2 - Compact Fast Charger', 'chargers', 18500, 17900, 14800, 150, 0.06, '/assets/products/apple-20w-gen2.webp', 'The essential Apple fast charger, now in a more compact design with GaN technology. Delivers 20W of clean power to your iPhone, iPad, or AirPods, charging your iPhone 16 to 50% in just 25 minutes. The foldable plug makes it the perfect travel companion.', 1, unixepoch('2026-06-16'), 1, 14800, '/assets/products/apple-20w-gen2.webp', 16800, 4.8, 1, 'Apple', 1, 1),

('apple-30w-usbc-power-adapter-compact', 'Apple 30W USB-C Power Adapter Compact - GaN Fast Charger', 'chargers', 32000, 30900, 25800, 85, 0.09, '/assets/products/apple-30w-compact.webp', 'Fast-charge your MacBook Air, iPad Pro, or iPhone 16 Pro Max with Apple''s most versatile power adapter. The GaN technology enables a remarkably small form factor while delivering 30W of efficient power through a single USB-C port with folding prongs.', 1, unixepoch('2026-06-16'), 1, 25800, '/assets/products/apple-30w-compact.webp', 29200, 4.8, 1, 'Apple', 1, 1),

('apple-35w-dual-usbc-compact', 'Apple 35W Dual USB-C Compact Power Adapter - Space Grey', 'chargers', 42000, 40900, 34500, 70, 0.11, '/assets/products/apple-35w-dual.webp', 'Charge two devices simultaneously from a single wall outlet with Apple''s dual-port charger. Intelligently distributes 35W across both USB-C ports, perfect for charging your iPhone and AirPods or Apple Watch at maximum speed while traveling light.', 1, unixepoch('2026-06-16'), 1, 34500, '/assets/products/apple-35w-dual.webp', 38800, 4.7, 1, 'Apple', 1, 1),

('apple-70w-usbc-power-adapter-fast', 'Apple 70W USB-C Power Adapter Fast Charger for MacBook', 'chargers', 55000, 53900, 45000, 45, 0.22, '/assets/products/apple-70w-fast.webp', 'Power your MacBook Air or 13-inch MacBook Pro at full speed with Apple''s 70W fast charger. USB-C Power Delivery 3.1 ensures optimal charging for your laptop while maintaining compatibility with iPhones and iPads for rapid top-ups when needed.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/apple-70w-fast.webp', 50500, 4.8, 1, 'Apple', 1, 0),

('apple-140w-usbc-gan-charger', 'Apple 140W USB-C GaN Power Adapter for MacBook Pro 16"', 'chargers', 85000, 82900, 68000, 30, 0.35, '/assets/products/apple-140w-gan.webp', 'The most powerful charger Apple has ever made. Delivers 140W through a single USB-C port using advanced GaN technology, fast-charging the 16-inch MacBook Pro to 50% in just 30 minutes. Backward compatible with all USB-C Apple devices.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/apple-140w-gan.webp', 78000, 4.8, 0, 'Apple', 1, 1),

('apple-magsafe-wireless-charger-25w', 'Apple MagSafe Wireless Charger 25W - Precision Magnetic Alignment', 'chargers', 42000, 40900, 34500, 80, 0.11, '/assets/products/apple-magsafe-25w.webp', 'The fastest MagSafe charging ever at 25W for iPhone 16 series. Perfectly aligned magnets snap into place for a secure, efficient wireless charge every time. The integrated aluminum base with soft-touch silicone protects your device while charging.', 1, unixepoch('2026-06-16'), 1, 34500, '/assets/products/apple-magsafe-25w.webp', 38800, 4.7, 1, 'Apple', 1, 1),

('apple-magsafe-battery-pack-2nd-gen', 'Apple MagSafe Battery Pack 2nd Gen 5000mAh - Lightning & USB-C', 'power', 95000, 92900, 78000, 40, 0.17, '/assets/products/apple-magsafe-battery-2.webp', 'The second-generation MagSafe Battery Pack features both Lightning and USB-C charging, a larger 5,000mAh capacity, and intelligent pass-through charging that powers your iPhone first, then recharges the pack. The tighter magnetic alignment ensures a secure connection.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/apple-magsafe-battery-2.webp', 88000, 4.6, 1, 'Apple', 1, 1),

('apple-watch-magnetic-charger-usbc', 'Apple Watch Magnetic Fast Charger USB-C 2m Cable - Braided', 'wearables', 25000, 23900, 19500, 60, 0.07, '/assets/products/apple-watch-charger-usbc.webp', 'Official Apple Watch fast charger with a premium braided 2-meter USB-C cable. Charges Apple Watch Series 7 and newer from 0 to 80% in just 45 minutes. The magnetic puck aligns perfectly with every Apple Watch model for reliable overnight charging.', 1, unixepoch('2026-06-16'), 1, 19500, '/assets/products/apple-watch-charger-usbc.webp', 22500, 4.7, 1, 'Apple', 1, 0),

