('apple-thunderbolt-4-pro-cable-1m', 'Apple Thunderbolt 4 Pro Cable 1m Braided - Space Black', 'accessories', 55000, 53900, 45000, 45, 0.10, '/assets/products/apple-tb4-cable-1m.webp', 'Unlock the full potential of your Thunderbolt 4 devices with 40Gbps data transfer, dual 6K display support, and 100W power delivery. The braided design with reinforced connectors is engineered to withstand the demands of professional workflows.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/apple-tb4-cable-1m.webp', 50500, 4.8, 0, 'Apple', 1, 1),

('apple-airtag-4-pack-bundle', 'Apple AirTag 4-Pack - Precision Finding with U2 Chip', 'accessories', 85000, 82900, 68000, 35, 0.08, '/assets/products/apple-airtag-4pack-bundle.webp', 'Never lose your keys, wallet, luggage, or backpack again with four AirTags featuring Apple''s U2 ultra-wideband chip. Precision Finding 2.0 guides you with exact distance and direction arrows. The built-in speaker plays a sound to help locate items hidden nearby.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/apple-airtag-4pack-bundle.webp', 78000, 4.8, 1, 'Apple', 1, 1),

('apple-magsafe-silicone-case-16-pro', 'Apple Silicone Case with MagSafe for iPhone 16 Pro - Midnight Blue', 'accessories', 42000, 40900, 34500, 50, 0.04, '/assets/products/apple-silicone-case-16pro.webp', 'Designed by Apple to perfectly complement your iPhone 16 Pro. The silky, soft-touch silicone exterior feels great in your hand, while the microfiber lining protects against scratches. Built-in magnets align perfectly for MagSafe charging and accessories.', 1, unixepoch('2026-06-16'), 1, 34500, '/assets/products/apple-silicone-case-16pro.webp', 38800, 4.6, 0, 'Apple', 1, 1),

('apple-magsafe-clear-case-16-pro-max', 'Apple Clear Case with MagSafe for iPhone 16 Pro Max - Crystal', 'accessories', 42000, 40900, 34500, 45, 0.04, '/assets/products/apple-clear-case-16promax.webp', 'Show off the color of your iPhone 16 Pro Max while protecting it with this optically clear polycarbonate case. The scratch-resistant coating and built-in MagSafe magnets make this the perfect blend of protection and aesthetics from Apple.', 1, unixepoch('2026-06-16'), 1, 34500, '/assets/products/apple-clear-case-16promax.webp', 38800, 4.6, 0, 'Apple', 1, 1),

