('apple-pencil-usbc-2026', 'Apple Pencil USB-C 2026 Edition with Hover Detection', 'accessories', 75000, 72900, 62000, 30, 0.02, '/assets/products/apple-pencil-usbc-2026.webp', 'The most affordable Apple Pencil now with hover detection that previews your mark before you make it. The USB-C port is hidden behind a sliding cap for quick pairing and charging. Perfect for note-taking, sketching, and marking up documents on iPad.', 1, unixepoch('2026-06-16'), 1, 62000, '/assets/products/apple-pencil-usbc-2026.webp', 69000, 4.7, 1, 'Apple', 1, 1),

